/**
 * @method
 * @name coinex#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://docs.coinex.com/api/v2/assets/deposit-withdrawal/http/list-all-deposit-withdrawal-config
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an associative dictionary of currencies
 */
func (this *Coinex) FetchCurrenciesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Coinex) fetchCurrenciesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	var response map[string]any = MapTyped(PanicOnError((<-this.V2PublicGetAssetsAllDepositWithdrawConfig(params)).Raw))
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "asset": {
	//                     "ccy": "CET",
	//                     "deposit_enabled": true,
	//                     "withdraw_enabled": true,
	//                     "inter_transfer_enabled": true,
	//                     "is_st": false
	//                 },
	//                 "chains": [
	//                     {
	//                         "chain": "CSC",
	//                         "min_deposit_amount": "0.8",
	//                         "min_withdraw_amount": "8",
	//                         "deposit_enabled": true,
	//                         "withdraw_enabled": true,
	//                         "deposit_delay_minutes": 0,
	//                         "safe_confirmations": 10,
	//                         "irreversible_confirmations": 20,
	//                         "deflation_rate": "0",
	//                         "withdrawal_fee": "0.026",
	//                         "withdrawal_precision": 8,
	//                         "memo": "",
	//                         "is_memo_required_for_deposit": false,
	//                         "explorer_asset_url": ""
	//                     },
	//                 ]
	//             }
	//         ],
	//         "message": "OK"
	//     }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseCurrencies(data)
	return nil
}
func (this *Coinex) ParseCurrency(coin any) any {
	var asset map[string]any = SafeMapTyped(coin, "asset")
	var currencyId *string = this.SafeString(asset, "ccy")
	var chains []any = SafeListTyped(coin, "chains")
	var code *string = this.SafeCurrencyCode(currencyId)
	var networks map[string]any = map[string]any{}
	for j := 0; j < len(chains); j++ {
		var chain any = func() any {
			if j >= 0 && j < len(chains) {
				return DerefScalar(chains[j])
			}
			return nil
		}()
		var networkId *string = this.SafeString(chain, "chain")
		var networkCode *string = this.NetworkIdToCode(networkId, code)
		if networkId == nil {
			continue
		}
		var network map[string]any = map[string]any{
			"id":        networkId,
			"network":   networkCode,
			"name":      nil,
			"active":    nil,
			"deposit":   this.SafeBool(chain, "deposit_enabled"),
			"withdraw":  this.SafeBool(chain, "withdraw_enabled"),
			"fee":       this.SafeNumber(chain, "withdrawal_fee"),
			"precision": this.ParseNumber(this.ParsePrecision(this.SafeString(chain, "withdrawal_precision"))),
			"limits": map[string]any{
				"amount": map[string]any{
					"min": nil,
					"max": nil,
				},
				"deposit": map[string]any{
					"min": this.SafeNumber(chain, "min_deposit_amount"),
					"max": nil,
				},
				"withdraw": map[string]any{
					"min": this.SafeNumber(chain, "min_withdraw_amount"),
					"max": nil,
				},
			},
			"info": chain,
		}
		if networkCode != nil {
			networks[*networkCode] = network
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"id":        currencyId,
		"code":      code,
		"name":      nil,
		"active":    nil,
		"deposit":   this.SafeBool(asset, "deposit_enabled"),
		"withdraw":  this.SafeBool(asset, "withdraw_enabled"),
		"fee":       nil,
		"precision": nil,
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"deposit": map[string]any{
				"min": nil,
				"max": nil,
			},
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"networks": networks,
		"type":     "crypto",
		"info":     coin,
	})
}

/**
 * @method
 * @name coinex#fetchMarkets
 * @description retrieves data on all markets for coinex
 * @see https://docs.coinex.com/api/v2/spot/market/http/list-market
 * @see https://docs.coinex.com/api/v2/futures/market/http/list-market
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Coinex) FetchMarketsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Coinex) fetchMarketsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var promisesUnresolved []any = []any{this.FetchSpotMarketsAsync(params), this.FetchContractMarketsAsync(params)}

	var promises []any = ListTyped(PanicOnError((<-promiseAll(promisesUnresolved))))
	var spotMarkets any = GetValue(promises, 0)
	var swapMarkets any = GetValue(promises, 1)

	ch <- this.ArrayConcat(spotMarkets, swapMarkets)
	return nil
}
func (this *Coinex) FetchSpotMarketsAsync(params any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchSpotMarketsBody(ch, params)
	return ch
}
func (this *Coinex) fetchSpotMarketsBody(ch chan any, params any) any {
	defer close(ch)
	defer ReturnPanicError(ch)

	var response map[string]any = MapTyped(PanicOnError((<-this.V2PublicGetSpotMarket(params)).Raw))
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "market": "BTCUSDT",
	//                 "taker_fee_rate": "0.002",
	//                 "maker_fee_rate": "0.002",
	//                 "min_amount": "0.0005",
	//                 "base_ccy": "BTC",
	//                 "quote_ccy": "USDT",
	//                 "base_ccy_precision": 8,
	//                 "quote_ccy_precision": 2,
	//                 "is_amm_available": true,
	//                 "is_margin_available": true,
	//                 "is_pre_trading_available": true,
	//                 "is_api_trading_available": true
	//             }
	//         ],
	//         "message": "OK"
	//     }
	//
	var markets []any = SafeListTyped(response, "data")
	var result []any = []any{}
	for i := 0; i < len(markets); i++ {
		var market any = func() any {
			if i >= 0 && i < len(markets) {
				return DerefScalar(markets[i])
			}
			return nil
		}()
		var id *string = this.SafeString(market, "market")
		var baseId *string = this.SafeString(market, "base_ccy")
		var quoteId *string = this.SafeString(market, "quote_ccy")
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		var symbol string = *base + "/" + *quote
		result = append(result, map[string]any{
			"id":             id,
			"symbol":         symbol,
			"base":           base,
			"quote":          quote,
			"settle":         nil,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       nil,
			"type":           "spot",
			"spot":           true,
			"margin":         this.SafeBool(market, "is_margin_available"),
			"swap":           false,
			"future":         false,
			"option":         false,
			"active":         this.SafeBool(market, "is_api_trading_available"),
			"contract":       false,
			"linear":         nil,
			"inverse":        nil,
			"taker":          this.SafeNumber(market, "taker_fee_rate"),
			"maker":          this.SafeNumber(market, "maker_fee_rate"),
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "base_ccy_precision"))),
				"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "quote_ccy_precision"))),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": this.SafeNumber(market, "min_amount"),
					"max": nil,
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"created": nil,
			"info":    market,
		})
	}

	ch <- result
	return nil
}
func (this *Coinex) FetchContractMarketsAsync(params any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchContractMarketsBody(ch, params)
	return ch
}
func (this *Coinex) fetchContractMarketsBody(ch chan any, params any) any {
	defer close(ch)
	defer ReturnPanicError(ch)

	var response map[string]any = MapTyped(PanicOnError((<-this.V2PublicGetFuturesMarket(params)).Raw))
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "base_ccy": "BTC",
	//                 "base_ccy_precision": 8,
	//                 "contract_type": "inverse",
	//                 "leverage": ["1","2","3","5","8","10","15","20","30","50","100"],
	//                 "maker_fee_rate": "0",
	//                 "market": "BTCUSD",
	//                 "min_amount": "10",
	//                 "open_interest_volume": "2566879",
	//                 "quote_ccy": "USD",
	//                 "quote_ccy_precision": 2,
	//                 "taker_fee_rate": "0"
	//             },
	//         ],
	//         "message": "OK"
	//     }
	//
	var markets []any = SafeListTyped(response, "data")
	var result []any = []any{}
	for i := 0; i < len(markets); i++ {
		var entry any = func() any {
			if i >= 0 && i < len(markets) {
				return DerefScalar(markets[i])
			}
			return nil
		}()
		var fees any = this.Fees
		var leverages []any = SafeListTyped(entry, "leverage")
		var subType *string = this.SafeString(entry, "contract_type")
		var linear bool = (subType != nil && *subType == "linear")
		var inverse bool = (subType != nil && *subType == "inverse")
		var id *string = this.SafeString(entry, "market")
		var baseId *string = this.SafeString(entry, "base_ccy")
		var quoteId *string = this.SafeString(entry, "quote_ccy")
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		var settleId *string = baseId
		if subType != nil && *subType == "linear" {
			settleId = SafeStringPtr("USDT")
		}
		var settle *string = this.SafeCurrencyCode(settleId)
		var symbol *string = SafeStringPtr(Add(*base+"/"+*quote+":", settle))
		var leveragesLength int = len(leverages)
		result = append(result, map[string]any{
			"id":             id,
			"symbol":         symbol,
			"base":           base,
			"quote":          quote,
			"settle":         settle,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       settleId,
			"type":           "swap",
			"spot":           false,
			"margin":         false,
			"swap":           true,
			"future":         false,
			"option":         false,
			"active":         nil,
			"contract":       true,
			"linear":         linear,
			"inverse":        inverse,
			"taker":          GetValue(GetValue(fees, "trading"), "taker"),
			"maker":          GetValue(GetValue(fees, "trading"), "maker"),
			"contractSize":   this.ParseNumber("1"),
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(entry, "base_ccy_precision"))),
				"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(entry, "quote_ccy_precision"))),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": this.SafeNumber(leverages, 0),
					"max": this.SafeNumber(leverages, leveragesLength-1),
				},
				"amount": map[string]any{
					"min": this.SafeNumber(entry, "min_amount"),
					"max": nil,
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"created": nil,
			"info":    entry,
		})
	}

	ch <- result
	return nil
}
func (this *Coinex) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	// Spot fetchTicker, fetchTickers
	//
	//     {
	//         "close": "62393.47",
	//         "high": "64106.41",
	//         "last": "62393.47",
	//         "low": "59650.01",
	//         "market": "BTCUSDT",
	//         "open": "61616.15",
	//         "period": 86400,
	//         "value": "28711273.4065667262",
	//         "volume": "461.76557205",
	//         "volume_buy": "11.41506354",
	//         "volume_sell": "7.3240169"
	//     }
	//
	// Swap fetchTicker, fetchTickers
	//
	//     {
	//         "close": "62480.08",
	//         "high": "64100",
	//         "index_price": "62443.05",
	//         "last": "62480.08",
	//         "low": "59600",
	//         "mark_price": "62443.05",
	//         "market": "BTCUSDT",
	//         "open": "61679.98",
	//         "period": 86400,
	//         "value": "180226025.69791713065326633165",
	//         "volume": "2900.2218",
	//         "volume_buy": "7.3847",
	//         "volume_sell": "6.1249"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketType string = func() string {
		if InOp(ticker, "mark_price") {
			return "swap"
		}
		return "spot"
	}()
	var marketId *string = this.SafeString(ticker, "market")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, nil, marketType)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	// on inverse contracts 'value' is denominated in the settle currency, not
	// the quote, so it is the quote volume only for spot and linear markets
	var quoteVolume *string = func() *string {
		if marketResolved["inverse"] == true {
			return nil
		}
		return this.SafeString(ticker, "value")
	}()
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     nil,
		"datetime":      nil,
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           nil,
		"bidVolume":     this.SafeString(ticker, "volume_buy"),
		"ask":           nil,
		"askVolume":     this.SafeString(ticker, "volume_sell"),
		"vwap":          nil,
		"open":          this.SafeString(ticker, "open"),
		"close":         this.SafeString(ticker, "close"),
		"last":          this.SafeString(ticker, "last"),
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    this.SafeString(ticker, "volume"),
		"quoteVolume":   quoteVolume,
		"markPrice":     this.SafeString(ticker, "mark_price"),
		"indexPrice":    this.SafeString(ticker, "index_price"),
		"info":          ticker,
	}, marketResolved)
}

/**
 * @method
 * @name coinex#fetchTicker
 * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
 * @see https://docs.coinex.com/api/v2/spot/market/http/list-market-ticker
 * @see https://docs.coinex.com/api/v2/futures/market/http/list-market-ticker
 * @param {string} symbol unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Coinex) FetchTickerAsync(symbol string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTickerBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Coinex) fetchTickerBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market": market["id"],
	}
	var response map[string]any = nil
	if market["swap"] == true {

		response = MapTyped(PanicOnError((<-this.V2PublicGetFuturesTicker(this.Extend(request, params))).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.V2PublicGetSpotTicker(this.Extend(request, params))).Raw))
	}
	//
	// Spot
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "close": "62393.47",
	//                 "high": "64106.41",
	//                 "last": "62393.47",
	//                 "low": "59650.01",
	//                 "market": "BTCUSDT",
	//                 "open": "61616.15",
	//                 "period": 86400,
	//                 "value": "28711273.4065667262",
	//                 "volume": "461.76557205",
	//                 "volume_buy": "11.41506354",
	//                 "volume_sell": "7.3240169"
	//             }
	//         ],
	//         "message": "OK"
	//     }
	//
	// Swap
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "close": "62480.08",
	//                 "high": "64100",
	//                 "index_price": "62443.05",
	//                 "last": "62480.08",
	//                 "low": "59600",
	//                 "mark_price": "62443.05",
	//                 "market": "BTCUSDT",
	//                 "open": "61679.98",
	//                 "period": 86400,
	//                 "value": "180226025.69791713065326633165",
	//                 "volume": "2900.2218",
	//                 "volume_buy": "7.3847",
	//                 "volume_sell": "6.1249"
	//             }
	//         ],
	//         "message": "OK"
	//     }
	//
	var data []any = SafeListTyped(response, "data")
	var result map[string]any = MapTyped(this.SafeDict(data, 0, map[string]any{}))

	ch <- this.ParseTicker(result, market)
	return nil
}

/**
 * @method
 * @name coinex#fetchTickers
 * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
 * @see https://docs.coinex.com/api/v2/spot/market/http/list-market-ticker
 * @see https://docs.coinex.com/api/v2/futures/market/http/list-market-ticker
 * @param {string[]|undefined} symbols unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Coinex) FetchTickersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Coinex) fetchTickersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)
	var market map[string]any = nil
	if !IsEqual(symbolsNormalized, nil) {
		var symbol *string = this.SafeString(symbolsNormalized, 0)
		market = this.Market(symbol)
	}
	marketType, query := this.HandleMarketTypeAndParams("fetchTickers", market, params)
	var response map[string]any = nil
	if marketType != nil && *marketType == "swap" {

		response = MapTyped(PanicOnError((<-this.V2PublicGetFuturesTicker(query)).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.V2PublicGetSpotTicker(query)).Raw))
	}
	//
	// Spot
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "close": "62393.47",
	//                 "high": "64106.41",
	//                 "last": "62393.47",
	//                 "low": "59650.01",
	//                 "market": "BTCUSDT",
	//                 "open": "61616.15",
	//                 "period": 86400,
	//                 "value": "28711273.4065667262",
	//                 "volume": "461.76557205",
	//                 "volume_buy": "11.41506354",
	//                 "volume_sell": "7.3240169"
	//             }
	//         ],
	//         "message": "OK"
	//     }
	//
	// Swap
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "close": "62480.08",
	//                 "high": "64100",
	//                 "index_price": "62443.05",
	//                 "last": "62480.08",
	//                 "low": "59600",
	//                 "mark_price": "62443.05",
	//                 "market": "BTCUSDT",
	//                 "open": "61679.98",
	//                 "period": 86400,
	//                 "value": "180226025.69791713065326633165",
	//                 "volume": "2900.2218",
	//                 "volume_buy": "7.3847",
	//                 "volume_sell": "6.1249"
	//             }
	//         ],
	//         "message": "OK"
	//     }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseTickers(data, symbolsNormalized)
	return nil
}

