/**
 * @method
 * @name coinex#fetchOrderBook
 * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://docs.coinex.com/api/v2/spot/market/http/list-market-depth
 * @see https://docs.coinex.com/api/v2/futures/market/http/list-market-depth
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Coinex) FetchOrderBookAsync(symbol string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOrderBookBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Coinex) fetchOrderBookBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit int64 = GetArgInt64(optionalArgs, 0, 20)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var limitValue any = limit
	if limitValue == nil {
		limitValue = 20
	}
	var request map[string]any = map[string]any{
		"market":   market["id"],
		"limit":    limitValue,
		"interval": "0",
	}
	var response map[string]any = nil
	if market["swap"] == true {

		response = MapTyped(PanicOnError((<-this.V2PublicGetFuturesDepth(this.Extend(request, params))).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.V2PublicGetSpotDepth(this.Extend(request, params))).Raw))
	}
	var data map[string]any = SafeMapTyped(response, "data")
	var depth map[string]any = MapTyped(this.SafeDict(data, "depth", map[string]any{}))
	var timestamp *int64 = this.SafeInteger(depth, "updated_at")

	ch <- this.ParseOrderBook(depth, symbol, timestamp)
	return nil
}
func (this *Coinex) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// Spot and Swap fetchTrades (public)
	//
	//     {
	//         "amount": "0.00049432",
	//         "created_at": 1713849825667,
	//         "deal_id": 4137517302,
	//         "price": "66251",
	//         "side": "buy"
	//     }
	//
	// Spot and Margin fetchMyTrades (private)
	//
	//     {
	//         "amount": "0.00010087",
	//         "created_at": 1714618087585,
	//         "deal_id": 4161200602,
	//         "margin_market": "",
	//         "market": "BTCUSDT",
	//         "order_id": 117654919342,
	//         "price": "57464.04",
	//         "side": "sell"
	//     }
	//
	// Swap fetchMyTrades (private)
	//
	//     {
	//         "deal_id": 1180222387,
	//         "created_at": 1714119054558,
	//         "market": "BTCUSDT",
	//         "side": "buy",
	//         "order_id": 136915589622,
	//         "price": "64376",
	//         "amount": "0.0001",
	//         "role": "taker",
	//         "fee": "0.0299",
	//         "fee_ccy": "USDT"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(trade, "created_at")
	var defaultType *string = this.SafeString(this.Options, "defaultType")
	if market != nil {
		defaultType = this.SafeString(market, "type")
	}
	var marketId *string = this.SafeString(trade, "market")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, nil, defaultType)
	var feeCostString *string = this.SafeString(trade, "fee")
	var fee map[string]any = nil
	if feeCostString != nil {
		var feeCurrencyId *string = this.SafeString(trade, "fee_ccy")
		var feeCurrencyCode *string = this.SafeCurrencyCode(feeCurrencyId)
		fee = map[string]any{
			"cost":     feeCostString,
			"currency": feeCurrencyCode,
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       marketResolved["symbol"],
		"id":           this.SafeString(trade, "deal_id"),
		"order":        this.SafeString(trade, "order_id"),
		"type":         nil,
		"side":         this.SafeString(trade, "side"),
		"takerOrMaker": this.SafeString(trade, "role"),
		"price":        this.SafeString(trade, "price"),
		"amount":       this.SafeString(trade, "amount"),
		"cost":         this.SafeString(trade, "deal_money"),
		"fee":          fee,
	}, marketResolved)
}

/**
 * @method
 * @name coinex#fetchTrades
 * @description get the list of the most recent trades for a particular symbol
 * @see https://docs.coinex.com/api/v2/spot/market/http/list-market-deals
 * @see https://docs.coinex.com/api/v2/futures/market/http/list-market-deals
 * @param {string} symbol unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of trades to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Coinex) FetchTradesAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTradesBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Coinex) fetchTradesBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market": market["id"],
	}
	if limit != nil {
		request["limit"] = mathMin(limit, 1000)
	}
	var response map[string]any = nil
	if market["swap"] == true {

		response = MapTyped(PanicOnError((<-this.V2PublicGetFuturesDeals(this.Extend(request, params))).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.V2PublicGetSpotDeals(this.Extend(request, params))).Raw))
	}

	//
	// Spot and Swap
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "amount": "0.00049432",
	//                 "created_at": 1713849825667,
	//                 "deal_id": 4137517302,
	//                 "price": "66251",
	//                 "side": "buy"
	//             },
	//         ],
	//         "message": "OK"
	//     }
	//
	ch <- this.ParseTrades(GetValue(response, "data"), market, since, limit)
	return nil
}

