func (this *Coinex) fetchTradingFeesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	typeVar, paramsMarketType := this.HandleMarketTypeAndParams("fetchTradingFees", nil, params)
	var response map[string]any = nil
	if typeVar != nil && *typeVar == "swap" {

		response = MapTyped(PanicOnError((<-this.V2PublicGetFuturesMarket(paramsMarketType)).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.V2PublicGetSpotMarket(paramsMarketType)).Raw))
	}
	var data []any = SafeListTyped(response, "data")
	var result map[string]any = map[string]any{}
	for i := 0; i < len(data); i++ {
		var entry any = func() any {
			if i >= 0 && i < len(data) {
				return DerefScalar(data[i])
			}
			return nil
		}()
		var marketId *string = this.SafeString(entry, "market")
		var market map[string]any = this.SafeMarket(marketId, nil, nil, typeVar)
		var symbol *string = SafeStringPtr(market["symbol"])
		AddElementToObject(result, symbol, this.ParseTradingFee(entry, market))
	}

	ch <- result
	return nil
}
