func (this *Coinex) cancelOrdersBody(ch chan any, ids any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " cancelOrders() requires a symbol argument"))
	}
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market": market["id"],
	}
	var trigger *bool = this.SafeBool2(params, "stop", "trigger")
	var paramsOmitted map[string]any = MapTyped(this.Omit(params, []any{"stop", "trigger"}))
	var response map[string]any = nil
	var requestIds []any = []any{}
	for i := 0; i < GetArrayLength(ids); i++ {
		requestIds = append(requestIds, ParseInt(GetValue(ids, i)))
	}
	if trigger != nil && *trigger == true {
		request["stop_ids"] = requestIds
	} else {
		request["order_ids"] = requestIds
	}
	if market["spot"] == true {
		if trigger != nil && *trigger == true {

			response = MapTyped(PanicOnError((<-this.V2PrivatePostSpotCancelBatchStopOrder(this.Extend(request, paramsOmitted))).Raw))
		} else {

			response = MapTyped(PanicOnError((<-this.V2PrivatePostSpotCancelBatchOrder(this.Extend(request, paramsOmitted))).Raw))
		}
	} else {
		request["market_type"] = "FUTURES"
		if trigger != nil && *trigger == true {

			response = MapTyped(PanicOnError((<-this.V2PrivatePostFuturesCancelBatchStopOrder(this.Extend(request, paramsOmitted))).Raw))
		} else {

			response = MapTyped(PanicOnError((<-this.V2PrivatePostFuturesCancelBatchOrder(this.Extend(request, paramsOmitted))).Raw))
		}
	}
	var data []any = SafeListTyped(response, "data")
	var results []any = []any{}
	for i := 0; i < len(data); i++ {
		var entry map[string]any = SafeMapTyped(data, i)
		var item map[string]any = MapTyped(this.SafeDict(entry, "data", map[string]any{}))
		var order map[string]any = MapTyped(this.ParseOrder(item, market))
		results = append(results, order)
	}

	ch <- results
	return nil
}

/**
 * @method
 * @name coinex#editOrder
 * @description edit a trade order
 * @see https://docs.coinex.com/api/v2/spot/order/http/edit-order
 * @see https://docs.coinex.com/api/v2/spot/order/http/edit-stop-order
 * @see https://docs.coinex.com/api/v2/futures/order/http/edit-order
 * @see https://docs.coinex.com/api/v2/futures/order/http/edit-stop-order
 * @param {string} id order id
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of the currency you want to trade in units of the base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {float} [params.triggerPrice] the price to trigger stop orders
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Coinex) EditOrderAsync(id string, symbol any, typeVar any, side any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.editOrderBody(ch, id, symbol, typeVar, side, optionalArgs...)
	return ch
}
func (this *Coinex) editOrderBody(ch chan any, id string, symbol any, typeVar any, side any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var amount *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = amount
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 1, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	this.CheckRequiredArgument("editOrder", symbol, "symbol")
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market": market["id"],
	}
	if amount != nil {
		request["amount"] = this.AmountToPrecision(symbol, amount)
	}
	if price != nil {
		request["price"] = this.PriceToPrecision(symbol, price)
	}
	var response any = nil
	var triggerPrice *string = this.SafeStringN(params, []any{"stopPrice", "triggerPrice", "trigger_price"})
	var paramsOmitted map[string]any = MapTyped(this.Omit(params, []any{"stopPrice", "triggerPrice"}))
	var isTriggerOrder bool = (triggerPrice != nil)
	if isTriggerOrder {
		request["trigger_price"] = this.PriceToPrecision(symbol, triggerPrice)
		request["stop_id"] = this.ParseToNumeric(id)
	} else {
		request["order_id"] = this.ParseToNumeric(id)
	}
	marginMode, paramsMarginMode := this.HandleMarginModeAndParams("editOrder", paramsOmitted)
	if market["spot"] == true {
		if marginMode != nil {
			request["market_type"] = "MARGIN"
		} else {
			request["market_type"] = "SPOT"
		}
		if isTriggerOrder {

			response = (<-this.V2PrivatePostSpotModifyStopOrder(this.Extend(request, paramsMarginMode)))
			PanicOnError(response)
		} else {

			response = (<-this.V2PrivatePostSpotModifyOrder(this.Extend(request, paramsMarginMode)))
			PanicOnError(response)
		}
	} else {
		request["market_type"] = "FUTURES"
		if isTriggerOrder {

			response = (<-this.V2PrivatePostFuturesModifyStopOrder(this.Extend(request, paramsMarginMode))).Raw
			PanicOnError(response)
		} else {

			response = (<-this.V2PrivatePostFuturesModifyOrder(this.Extend(request, paramsMarginMode))).Raw
			PanicOnError(response)
		}
	}
	var data map[string]any = MapTyped(this.SafeDict(response, "data", map[string]any{}))

	ch <- this.ParseOrder(data, market)
	return nil
}

/**
 * @method
 * @name coinex#editOrders
 * @description edit a list of trade orders
 * @see https://docs.coinex.com/api/v2/spot/order/http/edit-multi-order
 * @see https://docs.coinex.com/api/v2/futures/order/http/edit-multi-order
 * @param {Array} orders list of orders to edit, each object should contain the parameters required by editOrder, namely id, symbol, amount, price and params
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Coinex) EditOrdersAsync(orders any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.editOrdersBody(ch, orders, optionalArgs...)
	return ch
}
func (this *Coinex) editOrdersBody(ch chan any, orders any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var ordersRequests []any = []any{}
	var orderSymbols any = []any{}
	for i := 0; i < GetArrayLength(orders); i++ {
		var rawOrder map[string]any = SafeMapTyped(orders, i)
		var marketId *string = this.SafeString(rawOrder, "symbol")
		var market map[string]any = this.Market(marketId)
		if marketId != nil {
			AppendToArray(&orderSymbols, marketId)
		}
		var id *string = this.SafeString(rawOrder, "id")
		var amount *float64 = this.SafeNumber(rawOrder, "amount")
		var price *float64 = this.SafeNumber(rawOrder, "price")
		var orderParams any = this.SafeDict(rawOrder, "params", map[string]any{})
		var marginMode *string = nil
		marginMode, orderParams = this.HandleMarginModeAndParams("editOrders", orderParams)
		var market_type string = "SPOT"
		if market["swap"] == true {
			market_type = "FUTURES"
		} else if marginMode != nil {
			market_type = "MARGIN"
		}
		var orderRequest map[string]any = map[string]any{
			"order_id":    this.ParseToNumeric(id),
			"market":      market["id"],
			"market_type": market_type,
		}
		if amount != nil {
			orderRequest["amount"] = this.AmountToPrecision(marketId, amount)
		}
		if price != nil {
			orderRequest["price"] = this.PriceToPrecision(marketId, price)
		}
		ordersRequests = append(ordersRequests, this.Extend(orderRequest, orderParams))
	}
	orderSymbols = this.MarketSymbols(orderSymbols, nil, false, true, true)
	var firstSymbol *string = this.SafeString(orderSymbols, 0)
	var firstMarket map[string]any = this.Market(firstSymbol)
	var request map[string]any = map[string]any{
		"orders": ordersRequests,
	}
	var response any = nil
	if firstMarket["spot"] == true {

		response = (<-this.V2PrivatePostSpotBatchModifyOrder(this.Extend(request, params)))
		PanicOnError(response)
	} else {

		response = (<-this.V2PrivatePostFuturesBatchModifyOrder(this.Extend(request, params))).Raw
		PanicOnError(response)
	}
	var data []any = SafeListTypedDefault(response, "data", []any{})
	var result []any = []any{}
	for i := 0; i < len(data); i++ {
		var entry map[string]any = SafeMapTyped(data, i)
		var code *string = this.SafeString(entry, "code")
		var message *string = this.SafeString(entry, "message", "")
		if (code == nil || *code != "0") || ((message == nil || *message != "Success") && (message == nil || *message != "Succeeded") && (strings.ToLower(*message) != "ok") && ((data == nil))) {
			var feedback string = this.Id + " " + *message
			this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
			this.ThrowExactlyMatchedException(this.Exceptions["exact"], code, feedback)
			panic(ExchangeError(feedback))
		}
		var item map[string]any = MapTyped(this.SafeDict(entry, "data", map[string]any{}))
		var order map[string]any = MapTyped(this.ParseOrder(item))
		result = append(result, order)
	}

	ch <- result
	return nil
}

/**
 * @method
 * @name coinex#cancelOrder
 * @description cancels an open order
 * @see https://docs.coinex.com/api/v2/spot/order/http/cancel-order
 * @see https://docs.coinex.com/api/v2/spot/order/http/cancel-stop-order
 * @see https://docs.coinex.com/api/v2/spot/order/http/cancel-order-by-client-id
 * @see https://docs.coinex.com/api/v2/spot/order/http/cancel-stop-order-by-client-id
 * @see https://docs.coinex.com/api/v2/futures/order/http/cancel-order
 * @see https://docs.coinex.com/api/v2/futures/order/http/cancel-stop-order
 * @see https://docs.coinex.com/api/v2/futures/order/http/cancel-order-by-client-id
 * @see https://docs.coinex.com/api/v2/futures/order/http/cancel-stop-order-by-client-id
 * @param {string} id order id
 * @param {string} symbol unified symbol of the market the order was made in
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.clientOrderId] client order id, defaults to id if not passed
 * @param {boolean} [params.trigger] set to true for canceling a trigger order
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Coinex) CancelOrderAsync(id any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.cancelOrderBody(ch, id, optionalArgs...)
	return ch
}
func (this *Coinex) cancelOrderBody(ch chan any, id any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " cancelOrder() requires a symbol argument"))
	}
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var isTriggerOrder *bool = this.SafeBool2(params, "stop", "trigger")
	var swap *bool = SafeBoolPtr(market["swap"])
	var request map[string]any = map[string]any{
		"market": market["id"],
	}
	marginMode, paramsMarginMode := this.HandleMarginModeAndParams("cancelOrder", params)
	if swap != nil && *swap == true {
		request["market_type"] = "FUTURES"
	} else {
		if marginMode != nil {
			request["market_type"] = "MARGIN"
		} else {
			request["market_type"] = "SPOT"
		}
	}
	var clientOrderId *string = this.SafeString2(paramsMarginMode, "client_id", "clientOrderId")
	var paramsOmitted map[string]any = MapTyped(this.Omit(paramsMarginMode, []any{"stop", "trigger", "clientOrderId"}))
	var response any = nil
	if clientOrderId != nil {
		request["client_id"] = clientOrderId
		if isTriggerOrder != nil && *isTriggerOrder == true {
			if swap != nil && *swap == true {

				response = (<-this.V2PrivatePostFuturesCancelStopOrderByClientId(this.Extend(request, paramsOmitted))).Raw
				PanicOnError(response)
			} else {

				response = (<-this.V2PrivatePostSpotCancelStopOrderByClientId(this.Extend(request, paramsOmitted))).Raw
				PanicOnError(response)
			}
		} else {
			if swap != nil && *swap == true {

				response = (<-this.V2PrivatePostFuturesCancelOrderByClientId(this.Extend(request, paramsOmitted))).Raw
				PanicOnError(response)
			} else {

				response = (<-this.V2PrivatePostSpotCancelOrderByClientId(this.Extend(request, paramsOmitted))).Raw
				PanicOnError(response)
			}
		}
	} else {
		if isTriggerOrder != nil && *isTriggerOrder == true {
			request["stop_id"] = this.ParseToNumeric(id)
			if swap != nil && *swap == true {

				response = (<-this.V2PrivatePostFuturesCancelStopOrder(this.Extend(request, paramsOmitted))).Raw
				PanicOnError(response)
			} else {

				response = (<-this.V2PrivatePostSpotCancelStopOrder(this.Extend(request, paramsOmitted)))
				PanicOnError(response)
			}
		} else {
			request["order_id"] = this.ParseToNumeric(id)
			if swap != nil && *swap == true {

				response = (<-this.V2PrivatePostFuturesCancelOrder(this.Extend(request, paramsOmitted))).Raw
				PanicOnError(response)
			} else {

				response = (<-this.V2PrivatePostSpotCancelOrder(this.Extend(request, paramsOmitted)))
				PanicOnError(response)
			}
		}
	}
	var data any = nil
	if clientOrderId != nil {
		var rows []any = SafeListTyped(response, "data")
		data = this.SafeDict(func() any {
			if 0 >= 0 && 0 < len(rows) {
				return DerefScalar(rows[0])
			}
			return nil
		}(), "data", map[string]any{})
	} else {
		data = this.SafeDict(response, "data", map[string]any{})
	}

	ch <- this.ParseOrder(data, market)
	return nil
}

