func (this *Coinex) ParseDepositAddress(depositAddress any, optionalArgs ...any) any {
	//
	//     {
	//         "address": "1P1JqozxioQwaqPwgMAQdNDYNyaVSqgARq",
	//         "memo": ""
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var coinAddress *string = this.SafeString(depositAddress, "address", "")
	var parts []string = strings.Split(*coinAddress, ":")
	var address any = nil
	var tag any = nil
	var partsLength int = len(parts)
	if (partsLength > 1) && (GetValue(parts, 0) != "cfx") {
		address = GetValue(parts, 0)
		tag = GetValue(parts, 1)
	} else {
		address = coinAddress
	}
	return map[string]any{
		"info":     depositAddress,
		"currency": this.SafeCurrencyCode(nil, currency),
		"network":  nil,
		"address":  address,
		"tag":      this.SafeString(depositAddress, "memo", tag),
	}
}

