func (this *Coinex) ParseFundingRate(contract any, optionalArgs ...any) any {
	//
	// fetchFundingRate, fetchFundingRates, fetchFundingInterval
	//
	//     {
	//         "latest_funding_rate": "0",
	//         "latest_funding_time": 1715731200000,
	//         "mark_price": "61602.22",
	//         "market": "BTCUSDT",
	//         "max_funding_rate": "0.00375",
	//         "min_funding_rate": "-0.00375",
	//         "next_funding_rate": "0.00021074",
	//         "next_funding_time": 1715760000000
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var currentFundingTimestamp *int64 = this.SafeInteger(contract, "latest_funding_time")
	var futureFundingTimestamp *int64 = this.SafeInteger(contract, "next_funding_time")
	var fundingTimeString *string = this.SafeString(contract, "latest_funding_time")
	var nextFundingTimeString *string = this.SafeString(contract, "next_funding_time")
	var millisecondsInterval *string = Precise.StringSub(nextFundingTimeString, fundingTimeString)
	var marketId *string = this.SafeString(contract, "market")
	return map[string]any{
		"info":                     contract,
		"symbol":                   this.SafeSymbol(marketId, market, nil, "swap"),
		"markPrice":                this.SafeNumber(contract, "mark_price"),
		"indexPrice":               nil,
		"interestRate":             nil,
		"estimatedSettlePrice":     nil,
		"timestamp":                nil,
		"datetime":                 nil,
		"fundingRate":              this.SafeNumber(contract, "latest_funding_rate"),
		"fundingTimestamp":         currentFundingTimestamp,
		"fundingDatetime":          this.Iso8601(currentFundingTimestamp),
		"nextFundingRate":          this.SafeNumber(contract, "next_funding_rate"),
		"nextFundingTimestamp":     futureFundingTimestamp,
		"nextFundingDatetime":      this.Iso8601(futureFundingTimestamp),
		"previousFundingRate":      nil,
		"previousFundingTimestamp": nil,
		"previousFundingDatetime":  nil,
		"interval":                 this.ParseFundingInterval(millisecondsInterval),
	}
}
func (this *Coinex) ParseFundingInterval(interval *string) *string {
	var intervals map[string]any = map[string]any{
		"3600000":  "1h",
		"14400000": "4h",
		"28800000": "8h",
		"57600000": "16h",
		"86400000": "24h",
	}
	return this.SafeString(intervals, interval, interval)
}

