/**
 * @method
 * @name coinex#fetchFundingRateHistory
 * @description fetches historical funding rate prices
 * @see https://docs.coinex.com/api/v2/futures/market/http/list-market-funding-rate-history
 * @param {string} symbol unified symbol of the market to fetch the funding rate history for
 * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
 * @param {int} [limit] the maximum amount of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @param {int} [params.until] timestamp in ms of the latest funding rate
 * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure}
 */
func (this *Coinex) FetchFundingRateHistoryAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchFundingRateHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Coinex) fetchFundingRateHistoryBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " fetchFundingRateHistory() requires a symbol argument"))
	}
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchFundingRateHistory", "paginate", false)
	if paginate {

		var retRes507619 []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallDeterministicAsync("fetchFundingRateHistory", symbol, since, limit, "8h", paramsPaginate, 1000))))
		ch <- BoxAbsent(retRes507619)
		return nil
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market": market["id"],
	}
	if since != nil {
		request["start_time"] = since
	}
	if limit != nil {
		request["limit"] = limit
	}
	requestUntil, paramsUntil := this.HandleUntilOption("end_time", request, paramsPaginate)

	var response map[string]any = MapTyped(PanicOnError((<-this.V2PublicGetFuturesFundingRateHistory(this.Extend(requestUntil, paramsUntil))).Raw))
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "actual_funding_rate": "0",
	//                 "funding_time": 1715731221761,
	//                 "market": "BTCUSDT",
	//                 "theoretical_funding_rate": "0"
	//             },
	//         ],
	//         "message": "OK",
	//         "pagination": {
	//             "has_next": true
	//         }
	//     }
	//
	var data []any = SafeListTyped(response, "data")
	var rates []any = []any{}
	for i := 0; i < len(data); i++ {
		var entry any = func() any {
			if i >= 0 && i < len(data) {
				return DerefScalar(data[i])
			}
			return nil
		}()
		var marketId *string = this.SafeString(entry, "market")
		var symbolInner *string = this.SafeSymbol(marketId, market, nil, "swap")
		var timestamp *int64 = this.SafeInteger(entry, "funding_time")
		rates = append(rates, map[string]any{
			"info":        entry,
			"symbol":      symbolInner,
			"fundingRate": this.SafeNumber(entry, "actual_funding_rate"),
			"timestamp":   timestamp,
			"datetime":    this.Iso8601(timestamp),
		})
	}
	var sorted []any = this.SortBy(rates, "timestamp")

	ch <- this.FilterBySymbolSinceLimit(sorted, market["symbol"], since, limit)
	return nil
}
func (this *Coinex) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//
	//     {
	//         "deposit_id": 5173806,
	//         "created_at": 1714021652557,
	//         "tx_id": "d9f47d2550397c635cb89a8963118f8fe78ef048bc8b6f0caaeaa7dc6",
	//         "tx_id_display": "",
	//         "ccy": "USDT",
	//         "chain": "TRC20",
	//         "deposit_method": "ON_CHAIN",
	//         "amount": "30",
	//         "actual_amount": "",
	//         "to_address": "TYewD2pVWDUwfNr9A",
	//         "confirmations": 20,
	//         "status": "FINISHED",
	//         "tx_explorer_url": "https://tronscan.org/#/transaction",
	//         "to_addr_explorer_url": "https://tronscan.org/#/address",
	//         "remark": ""
	//     }
	//
	// fetchWithdrawals and withdraw
	//
	//     {
	//         "withdraw_id": 259364,
	//         "created_at": 1701323541548,
	//         "withdraw_method": "ON_CHAIN",
	//         "ccy": "USDT",
	//         "amount": "23.845744",
	//         "actual_amount": "22.445744",
	//         "chain": "TRC20",
	//         "tx_fee": "1.4",
	//         "fee_asset": "USDT",
	//         "fee_amount": "1.4",
	//         "to_address": "T8t5i2454dhdhnnnGdi49vMbihvY",
	//         "memo": "",
	//         "tx_id": "1237623941964de9954ed2e36640228d78765c1026",
	//         "confirmations": 18,
	//         "explorer_address_url": "https://tronscan.org/#/address",
	//         "explorer_tx_url": "https://tronscan.org/#/transaction",
	//         "remark": "",
	//         "status": "finished"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var address *string = this.SafeString(transaction, "to_address")
	var tag *string = this.SafeString(transaction, "memo")
	if tag != nil {
		if GetLength(tag) < 1 {
			tag = nil
		}
	}
	var remark *string = this.SafeString(transaction, "remark")
	if remark != nil {
		if GetLength(remark) < 1 {
			remark = nil
		}
	}
	var txid *string = this.SafeString(transaction, "tx_id")
	if txid != nil {
		if GetLength(txid) < 1 {
			txid = nil
		}
	}
	var currencyId *string = this.SafeString(transaction, "ccy")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var timestamp *int64 = this.SafeInteger(transaction, "created_at")
	var typeVar string = "deposit"
	if InOp(transaction, "withdraw_id") {
		typeVar = "withdrawal"
	}
	var networkId *string = this.SafeString(transaction, "chain")
	var feeCost *string = this.SafeString(transaction, "tx_fee")
	var transferMethod *string = this.SafeStringLower2(transaction, "withdraw_method", "deposit_method")
	var internal bool = (transferMethod != nil && *transferMethod == "local")
	var amount *float64 = this.SafeNumber(transaction, "actual_amount")
	if amount == nil {
		amount = this.SafeNumber(transaction, "amount")
	}
	if typeVar == "deposit" {
		feeCost = SafeStringPtr("0")
	}
	var feeCurrencyId *string = this.SafeString2(transaction, "fee_asset", "fee_ccy") // https://github.com/ccxt/ccxt/issues/25153
	var fee map[string]any = map[string]any{
		"cost":     this.ParseNumber(feeCost),
		"currency": this.SafeCurrencyCode(feeCurrencyId),
	}
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString2(transaction, "withdraw_id", "deposit_id"),
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     this.NetworkIdToCode(networkId, code),
		"address":     address,
		"addressTo":   address,
		"addressFrom": nil,
		"tag":         tag,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      amount,
		"currency":    code,
		"status":      this.ParseTransactionStatus(this.SafeString(transaction, "status")),
		"updated":     nil,
		"fee":         fee,
		"comment":     remark,
		"internal":    internal,
	}
}

/**
 * @method
 * @name coinex#transfer
 * @description transfer currency internally between wallets on the same account
 * @see https://docs.coinex.com/api/v2/assets/transfer/http/transfer
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount account to transfer from
 * @param {string} toAccount account to transfer to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.symbol] unified ccxt symbol, required when either the fromAccount or toAccount is margin
 * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Coinex) TransferAsync(code string, amount any, fromAccount any, toAccount string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.transferBody(ch, code, amount, fromAccount, toAccount, optionalArgs...)
	return ch
}
func (this *Coinex) transferBody(ch chan any, code string, amount any, fromAccount any, toAccount string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = this.Currency(code)
	var amountToPrecision any = this.CurrencyToPrecision(code, amount)
	var accountsByType map[string]any = SafeMapTyped(this.Options, "accountsByType")
	var fromId *string = this.SafeString(accountsByType, fromAccount, fromAccount)
	var toId *string = this.SafeString(accountsByType, toAccount, toAccount)
	var request map[string]any = map[string]any{
		"ccy":               currency["id"],
		"amount":            amountToPrecision,
		"from_account_type": fromId,
		"to_account_type":   toId,
	}
	var paramsOmitted any = params
	if (IsEqual(fromAccount, "margin")) || (toAccount == "margin") {
		paramsOmitted = this.Omit(params, "symbol")
	}
	if (IsEqual(fromAccount, "margin")) || (toAccount == "margin") {
		var symbol *string = this.SafeString(params, "symbol")
		if symbol == nil {
			panic(ArgumentsRequired(this.Id + " transfer() the symbol parameter must be defined for a margin account"))
		}
		request["market"] = this.MarketId(symbol)
	}
	if (!IsEqual(fromAccount, "spot")) && (toAccount != "spot") {
		panic(BadRequest(this.Id + " transfer() can only be between spot and swap, or spot and margin, either the fromAccount or toAccount must be spot"))
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.V2PrivatePostAssetsTransfer(this.Extend(request, paramsOmitted))).Raw))

	//
	//     {
	//         "code": 0,
	//         "data": {},
	//         "message": "OK"
	//     }
	//
	ch <- this.Extend(this.ParseTransfer(response, currency), map[string]any{
		"amount":      this.ParseNumber(amountToPrecision),
		"fromAccount": fromAccount,
		"toAccount":   toAccount,
	})
	return nil
}
func (this *Coinex) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"0":        "ok",
		"SUCCESS":  "ok",
		"OK":       "ok",
		"finished": "ok",
		"FINISHED": "ok",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Coinex) ParseTransfer(transfer any, optionalArgs ...any) any {
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.SafeInteger(transfer, "created_at")
	var currencyId *string = this.SafeString(transfer, "ccy")
	var fromId *string = this.SafeString(transfer, "from_account_type")
	var toId *string = this.SafeString(transfer, "to_account_type")
	var accountsById map[string]any = SafeMapTyped(this.Options, "accountsById")
	return map[string]any{
		"id":          nil,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"currency":    this.SafeCurrencyCode(currencyId, currency),
		"amount":      this.SafeNumber(transfer, "amount"),
		"fromAccount": this.SafeString(accountsById, fromId, fromId),
		"toAccount":   this.SafeString(accountsById, toId, toId),
		"status":      this.ParseTransferStatus(this.SafeString2(transfer, "code", "status")),
	}
}

