/**
 * @method
 * @name coinex#fetchDeposits
 * @description fetch all deposits made to an account
 * @see https://docs.coinex.com/api/v2/assets/deposit-withdrawal/http/list-deposit-history
 * @param {string} [code] unified currency code
 * @param {int} [since] the earliest time in ms to fetch deposits for
 * @param {int} [limit] the maximum number of deposit structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [transaction structures]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Coinex) FetchDepositsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchDepositsBody(ch, optionalArgs...)
	return ch
}
func (this *Coinex) fetchDepositsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var request map[string]any = map[string]any{}
	var currency map[string]any = nil
	if code != nil {
		currency = this.Currency(code)
		request["ccy"] = GetValue(currency, "id")
	}
	if limit != nil {
		request["limit"] = limit
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.V2PrivateGetAssetsDepositHistory(this.Extend(request, params))).Raw))
	//
	//     {
	//         "data": [
	//             {
	//                 "deposit_id": 5173806,
	//                 "created_at": 1714021652557,
	//                 "tx_id": "d9f47d2550397c635cb89a8963118f8fe78ef048bc8b6f0caaeaa7dc6",
	//                 "tx_id_display": "",
	//                 "ccy": "USDT",
	//                 "chain": "TRC20",
	//                 "deposit_method": "ON_CHAIN",
	//                 "amount": "30",
	//                 "actual_amount": "",
	//                 "to_address": "TYewD2pVWDUwfNr9A",
	//                 "confirmations": 20,
	//                 "status": "FINISHED",
	//                 "tx_explorer_url": "https://tronscan.org/#/transaction",
	//                 "to_addr_explorer_url": "https://tronscan.org/#/address",
	//                 "remark": ""
	//             },
	//         ],
	//         "paginatation": {
	//             "total": 8,
	//             "has_next": true
	//         },
	//         "code": 0,
	//         "message": "OK"
	//     }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseTransactions(data, currency, since, limit)
	return nil
}
func (this *Coinex) ParseIsolatedBorrowRate(info any, optionalArgs ...any) any {
	//
	//     {
	//         "market": "BTCUSDT",
	//         "ccy": "USDT",
	//         "leverage": 10,
	//         "min_amount": "60",
	//         "max_amount": "500000",
	//         "daily_interest_rate": "0.001"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(info, "market")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, nil, "spot")
	var currency *string = this.SafeString(info, "ccy")
	var rate *float64 = this.SafeNumber(info, "daily_interest_rate")
	var baseRate *float64 = nil
	var quoteRate *float64 = nil
	if IsEqual(currency, marketResolved["baseId"]) {
		baseRate = rate
	} else if IsEqual(currency, marketResolved["quoteId"]) {
		quoteRate = rate
	}
	return map[string]any{
		"symbol":    marketResolved["symbol"],
		"base":      marketResolved["base"],
		"baseRate":  baseRate,
		"quote":     marketResolved["quote"],
		"quoteRate": quoteRate,
		"period":    86400000,
		"timestamp": nil,
		"datetime":  nil,
		"info":      info,
	}
}

/**
 * @method
 * @name coinex#fetchIsolatedBorrowRate
 * @description fetch the rate of interest to borrow a currency for margin trading
 * @see https://docs.coinex.com/api/v2/assets/loan-flat/http/list-margin-interest-limit
 * @param {string} symbol unified symbol of the market to fetch the borrow rate for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} params.code unified currency code
 * @returns {object} an [isolated borrow rate structure]{@link https://docs.ccxt.com/?id=isolated-borrow-rate-structure}
 */
func (this *Coinex) FetchIsolatedBorrowRateAsync(symbol string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchIsolatedBorrowRateBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Coinex) fetchIsolatedBorrowRateBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var code *string = this.SafeString(params, "code")
	if code == nil {
		panic(ArgumentsRequired(this.Id + " fetchIsolatedBorrowRate() requires a code parameter"))
	}
	var paramsOmitted map[string]any = MapTyped(this.Omit(params, "code"))
	var currency map[string]any = this.Currency(code)
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market": market["id"],
		"ccy":    currency["id"],
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.V2PrivateGetAssetsMarginInterestLimit(this.Extend(request, paramsOmitted))).Raw))
	//
	//     {
	//         "code": 0,
	//         "data": {
	//             "market": "BTCUSDT",
	//             "ccy": "USDT",
	//             "leverage": 10,
	//             "min_amount": "60",
	//             "max_amount": "500000",
	//             "daily_interest_rate": "0.001"
	//         },
	//         "message": "OK"
	//     }
	//
	var data map[string]any = MapTyped(this.SafeDict(response, "data", map[string]any{}))

	ch <- this.ParseIsolatedBorrowRate(data, market)
	return nil
}

