/**
 * @method
 * @name coinex#fetchDepositWithdrawFees
 * @description fetch the fees for deposits and withdrawals
 * @see https://docs.coinex.com/api/v2/assets/deposit-withdrawal/http/list-all-deposit-withdrawal-config
 * @param {string[]} [codes] list of unified currency codes
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [fee structures]{@link https://docs.ccxt.com/?id=fee-structure}
 */
func (this *Coinex) FetchDepositWithdrawFeesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchDepositWithdrawFeesBody(ch, optionalArgs...)
	return ch
}
func (this *Coinex) fetchDepositWithdrawFeesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var codes []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = codes
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.V2PublicGetAssetsAllDepositWithdrawConfig(params)).Raw))
	//
	//     {
	//         "code": 0,
	//         "data": [
	//             {
	//                 "asset": {
	//                     "ccy": "CET",
	//                     "deposit_enabled": true,
	//                     "withdraw_enabled": true,
	//                     "inter_transfer_enabled": true,
	//                     "is_st": false
	//                 },
	//                 "chains": [
	//                     {
	//                         "chain": "CSC",
	//                         "min_deposit_amount": "0.8",
	//                         "min_withdraw_amount": "8",
	//                         "deposit_enabled": true,
	//                         "withdraw_enabled": true,
	//                         "deposit_delay_minutes": 0,
	//                         "safe_confirmations": 10,
	//                         "irreversible_confirmations": 20,
	//                         "deflation_rate": "0",
	//                         "withdrawal_fee": "0.026",
	//                         "withdrawal_precision": 8,
	//                         "memo": "",
	//                         "is_memo_required_for_deposit": false,
	//                         "explorer_asset_url": ""
	//                     },
	//                 ]
	//             }
	//         ],
	//         "message": "OK"
	//     }
	//
	var data []any = SafeListTyped(response, "data")
	var result map[string]any = map[string]any{}
	for i := 0; i < len(data); i++ {
		var item map[string]any = SafeMapTyped(data, i)
		var asset map[string]any = SafeMapTyped(item, "asset")
		var currencyId *string = this.SafeString(asset, "ccy")
		if currencyId == nil {
			continue
		}
		var code *string = this.SafeCurrencyCode(currencyId)
		if (codes == nil) || this.InArray(code, codes) {
			if code != nil {
				AddElementToObject(result, code, this.ParseDepositWithdrawFee(item))
			}
		}
	}

	ch <- result
	return nil
}
func (this *Coinex) ParseDepositWithdrawFee(fee any, optionalArgs ...any) any {
	//
	//     {
	//         "asset": {
	//             "ccy": "USDT",
	//             "deposit_enabled": true,
	//             "withdraw_enabled": true,
	//             "inter_transfer_enabled": true,
	//             "is_st": false
	//         },
	//         "chains": [
	//             {
	//                 "chain": "TRC20",
	//                 "min_deposit_amount": "2.4",
	//                 "min_withdraw_amount": "2.4",
	//                 "deposit_enabled": true,
	//                 "withdraw_enabled": true,
	//                 "deposit_delay_minutes": 0,
	//                 "safe_confirmations": 10,
	//                 "irreversible_confirmations": 20,
	//                 "deflation_rate": "0",
	//                 "withdrawal_fee": "2.4",
	//                 "withdrawal_precision": 6,
	//                 "memo": "",
	//                 "is_memo_required_for_deposit": false,
	//                 "explorer_asset_url": "https://tronscan.org/#/token20/TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t"
	//             },
	//         ]
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var result map[string]any = map[string]any{
		"info": fee,
		"withdraw": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"deposit": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"networks": map[string]any{},
	}
	var chains []any = SafeListTyped(fee, "chains")
	var asset map[string]any = SafeMapTyped(fee, "asset")
	for i := 0; i < len(chains); i++ {
		var entry map[string]any = SafeMapTyped(chains, i)
		var isWithdrawEnabled *bool = this.SafeBool(entry, "withdraw_enabled")
		if isWithdrawEnabled != nil && *isWithdrawEnabled == true {
			AddElementToObject(result["withdraw"], "fee", this.SafeNumber(entry, "withdrawal_fee"))
			AddElementToObject(result["withdraw"], "percentage", false)
			var networkId *string = this.SafeString(entry, "chain")
			if (networkId != nil) && (networkId == nil || *networkId != "") {
				var currencyId *string = this.SafeString(asset, "ccy")
				var feeCode *string = this.SafeCurrencyCode(currencyId, currency)
				var networkCode *string = this.NetworkIdToCode(networkId, feeCode)
				if networkCode != nil {
					AddElementToObject(result["networks"], networkCode, map[string]any{
						"withdraw": map[string]any{
							"fee":        this.SafeNumber(entry, "withdrawal_fee"),
							"percentage": false,
						},
						"deposit": map[string]any{
							"fee":        nil,
							"percentage": nil,
						},
					})
				}
			}
		}
	}
	return result
}

