func (this *Coinex) HandleMarginModeAndParams(methodName any, optionalArgs ...any) (*string, map[string]any) {
	/**
	 * @ignore
	 * @method
	 * @description marginMode specified by params["marginMode"], this.options["marginMode"], this.options["defaultMarginMode"], params["margin"] = true or this.options["defaultType"] = 'margin'
	 * @param {object} params extra parameters specific to the exchange API endpoint
	 * @returns {Array} the marginMode in lowercase
	 */
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var defaultValue *string = GetArgStringPtr(optionalArgs, 1, nil)
	_ = defaultValue
	var defaultType *string = this.SafeString(this.Options, "defaultType")
	var isMargin *bool = this.SafeBool(params, "margin", false)
	marginModeValue, paramsMarginMode := this.Exchange.HandleMarginModeAndParams(methodName, params, defaultValue)
	var marginMode any = marginModeValue
	if IsEqual(marginMode, nil) {
		if (defaultType != nil && *defaultType == "margin") || (isMargin != nil && *isMargin == true) {
			marginMode = "isolated"
		}
	}
	return SafeStringPtr(marginMode), MapTyped(paramsMarginMode)
}
func (this *Coinex) Nonce() any {
	return this.Milliseconds()
}
func (this *Coinex) Sign(path string, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, []any{})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	var body *string = GetArgStringPtr(optionalArgs, 4, nil)
	_ = body
	var pathValue string = this.ImplodeParams(path, params)
	var version any = GetValue(api, 0)
	var requestUrl any = GetValue(api, 1)
	var apiUrl *string = this.SafeString(GetValue(this.Urls, "api"), requestUrl)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url any = Add(Add(Add(*apiUrl+"/", version), "/"), pathValue)
	var query any = this.Omit(params, this.ExtractParams(pathValue))
	var nonce string = ToString(this.Nonce())
	if method == "POST" {
		var parts []string = strings.Split(pathValue, "/")
		var firstPart *string = this.SafeString(parts, 0, "")
		var numParts int = len(parts)
		var lastPart *string = this.SafeString(parts, numParts-1, "")
		var lastWords []string = strings.Split(*lastPart, "_")
		var numWords int = len(lastWords)
		var lastWord *string = this.SafeString(lastWords, numWords-1, "")
		if (firstPart != nil && *firstPart == "order") && ((lastWord != nil && *lastWord == "limit") || (lastWord != nil && *lastWord == "market")) {
			// inject in implicit API calls
			// POST /order/limit - Place limit orders
			// POST /order/market - Place market orders
			// POST /order/stop/limit - Place stop limit orders
			// POST /order/stop/market - Place stop market orders
			// POST /perpetual/v1/order/put_limit - Place limit orders
			// POST /perpetual/v1/order/put_market - Place market orders
			// POST /perpetual/v1/order/put_stop_limit - Place stop limit orders
			// POST /perpetual/v1/order/put_stop_market - Place stop market orders
			var clientOrderId *string = this.SafeString(params, "client_id")
			if clientOrderId == nil {
				var defaultId string = "x-167673045"
				var brokerId *string = this.SafeString(this.Options, "brokerId", defaultId)
				AddElementToObject(query, "client_id", *brokerId+"_"+this.Uuid16())
			}
		}
	}
	var signedHeaders any = nil
	var signedBody any = nil
	if requestUrl == "perpetualPrivate" {
		this.CheckRequiredCredentials()
		query = this.Extend(map[string]any{
			"access_id": this.ApiKey,
			"timestamp": nonce,
		}, query)
		query = this.Keysort(query)
		var urlencoded string = this.Rawencode(query)
		var signature any = this.Hash(this.Encode(Add(urlencoded+"&secret_key=", this.Secret)), sha256)
		signedHeaders = map[string]any{
			"Authorization": ToLower(signature),
			"AccessId":      this.ApiKey,
		}
		if (method == "GET") || (method == "PUT") {
			url = Add(url, "?"+urlencoded)
		} else {
			AddElementToObject(signedHeaders, "Content-Type", "application/x-www-form-urlencoded")
			signedBody = urlencoded
		}
	} else if ((requestUrl == "public")) || ((requestUrl == "perpetualPublic")) {
		if len(ObjectKeys(query)) > 0 {
			url = Add(url, "?"+this.Urlencode(query))
		}
	} else {
		if version == "v1" {
			this.CheckRequiredCredentials()
			query = this.Extend(map[string]any{
				"access_id": this.ApiKey,
				"tonce":     nonce,
			}, query)
			query = this.Keysort(query)
			var urlencoded string = this.Rawencode(query)
			var signature any = this.Hash(this.Encode(Add(urlencoded+"&secret_key=", this.Secret)), md5)
			signedHeaders = map[string]any{
				"Authorization": ToUpper(signature),
				"Content-Type":  "application/json",
			}
			if (method == "GET") || (method == "DELETE") || (method == "PUT") {
				url = Add(url, "?"+urlencoded)
			} else {
				signedBody = this.Json(query)
			}
		} else if version == "v2" {
			this.CheckRequiredCredentials()
			query = this.Keysort(query)
			var urlencoded string = this.Rawencode(query)
			var preparedString any = Add(Add(Add(method+"/", version), "/"), pathValue)
			if method == "POST" {
				signedBody = this.Json(query)
				preparedString = Add(preparedString, signedBody)
			} else if urlencoded != "" {
				preparedString = Add(preparedString, "?"+urlencoded)
			}
			preparedString = Add(preparedString, Add(nonce, this.Secret))
			var signature any = this.Hash(this.Encode(preparedString), sha256)
			signedHeaders = map[string]any{
				"Content-Type":       "application/json",
				"Accept":             "application/json",
				"X-COINEX-KEY":       this.ApiKey,
				"X-COINEX-SIGN":      signature,
				"X-COINEX-TIMESTAMP": nonce,
			}
			if method != "POST" {
				if urlencoded != "" {
					url = Add(url, "?"+urlencoded)
				}
			}
		}
	}
	var headersResolved any = func() any {
		if signedHeaders != nil {
			return signedHeaders
		}
		return headers
	}()
	var bodyResolved any = func() any {
		if signedBody != nil {
			return signedBody
		}
		return body
	}()
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResolved,
		"headers": headersResolved,
	}
}
func (this *Coinex) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsEqual(response, nil) {
		return nil
	}
	var code *string = this.SafeString(response, "code")
	var data any = this.SafeValue(response, "data")
	var message *string = this.SafeString(response, "message", "")
	if (code == nil || *code != "0") || ((message == nil || *message != "Success") && (message == nil || *message != "Succeeded") && (strings.ToLower(*message) != "ok") && (IsEqual(data, nil))) {
		var feedback string = this.Id + " " + *message
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], code, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

